"""IDA Free decompiler backend (assist-only, non-headless)."""

from __future__ import annotations

import json
import os
import re
import shutil
from typing import Dict, List, Optional, Tuple

from .base import BackendCapability, DecompiledFunction, DecompilerBackend


def ingest_exported_dir(export_dir: str) -> Dict[int, DecompiledFunction]:
    """Ingest decompiled C functions from an export directory generated by ida_export_c.py.

    Args:
        export_dir: Path to directory containing manifest.json and exported .c files.

    Returns:
        Dict mapping function virtual address to DecompiledFunction.
    """
    if not os.path.isdir(export_dir):
        raise FileNotFoundError(f"Export directory '{export_dir}' does not exist or is not a directory")

    manifest_path = os.path.join(export_dir, "manifest.json")
    results: Dict[int, DecompiledFunction] = {}

    if os.path.isfile(manifest_path):
        with open(manifest_path, "r", encoding="utf-8") as f:
            manifest = json.load(f)

        raw_funcs = manifest.get("functions", [])
        if isinstance(raw_funcs, dict):
            raw_funcs = list(raw_funcs.values())

        for item in raw_funcs:
            name = str(item.get("name", ""))
            va = int(item.get("va", 0))
            filename = item.get("file", f"{name}.c")
            proto = str(item.get("prototype", ""))
            warnings = list(item.get("warnings", []))

            c_file_path = os.path.join(export_dir, filename)
            c_code = ""
            if os.path.isfile(c_file_path):
                with open(c_file_path, "r", encoding="utf-8") as cf:
                    c_code = cf.read()
            else:
                warnings.append(f"Exported C file '{filename}' was not found")

            results[va] = DecompiledFunction(
                name=name,
                va=va,
                c_code=c_code,
                prototype=proto,
                backend="idafree",
                warnings=warnings,
            )
        return results

    # Fallback when manifest.json is absent: scan *.c files directly
    c_files = [f for f in os.listdir(export_dir) if f.endswith(".c")]
    va_pattern = re.compile(r"(?:va|at|addr)[:=\s]+(0x[0-9a-fA-F]+|\d+)", re.IGNORECASE)
    sub_pattern = re.compile(r"sub_([0-9a-fA-F]+)", re.IGNORECASE)

    for cf_name in c_files:
        full_path = os.path.join(export_dir, cf_name)
        with open(full_path, "r", encoding="utf-8") as cf:
            content = cf.read()

        va: Optional[int] = None
        # Check comment header for VA
        match = va_pattern.search(content[:500])
        if match:
            va = int(match.group(1), 0)
        else:
            sub_match = sub_pattern.search(cf_name)
            if sub_match:
                va = int(sub_match.group(1), 16)

        if va is not None:
            func_name = os.path.splitext(cf_name)[0]
            results[va] = DecompiledFunction(
                name=func_name,
                va=va,
                c_code=content,
                prototype="",
                backend="idafree",
                warnings=[],
            )

    return results


class IDAFreeBackend(DecompilerBackend):
    """Universal IDA Free backend (assist_only=True, headless=False)."""

    @property
    def name(self) -> str:
        return "idafree"

    def _find_idafree_path(self) -> Optional[str]:
        """Detect IDA Free installation directory or executable without launching GUI."""
        env_dir = os.environ.get("IDAFREEDIR") or os.environ.get("IDA_FREE_DIR")
        if env_dir and os.path.isdir(env_dir):
            for cand in ["ida64", "ida"]:
                path = os.path.join(env_dir, cand)
                if os.path.isfile(path) and os.access(path, os.X_OK):
                    return path
            return env_dir

        standard_dirs = [
            "/opt/ida-free",
            "/opt/idafree",
            os.path.expanduser("~/ida-free"),
            os.path.expanduser("~/idafree"),
        ]
        for sdir in standard_dirs:
            if os.path.isdir(sdir):
                for cand in ["ida64", "ida"]:
                    path = os.path.join(sdir, cand)
                    if os.path.isfile(path) and os.access(path, os.X_OK):
                        return path
                return sdir

        # Check if ida in PATH specifically points to an IDA Free path
        for cand in ["ida64", "ida"]:
            which = shutil.which(cand)
            if which and "free" in which.lower():
                return which

        return None

    def probe(self) -> BackendCapability:
        """Detect IDA Free installation without launching GUI or triggering license prompts."""
        path = self._find_idafree_path()
        if path:
            return BackendCapability(
                name=self.name,
                available=True,
                headless=False,
                assist_only=True,
                path=path,
                reason="IDA Free installation detected (assist-only mode)",
            )

        return BackendCapability(
            name=self.name,
            available=False,
            headless=False,
            assist_only=True,
            path=None,
            reason="IDA Free installation not found (checked IDAFREEDIR, /opt/ida-free, PATH)",
        )

    def decompile_batch(
        self, elf_path: str, funcs: List[Tuple[int, str]], timeout: int = 120
    ) -> Dict[int, DecompiledFunction]:
        """IDA Free does not support unattended headless batch decompilation."""
        raise RuntimeError(
            "IDA Free is an assist-only backend (cannot run headlessly). "
            "Export decompiled functions using scripts/ida_export_c.py in IDA Free GUI, "
            "then pass --decompile-assist <export_dir>."
        )
